const domain = items[0].json.domain;
const gscProperty = items[0].json.gsc_property;
const now = new Date();

const fmt = (d) => d.toISOString().split('T')[0];

// Find the most recently completed Monday-Sunday week.
// getDay(): 0=Sun,1=Mon...6=Sat
const dayOfWeek = now.getDay();
const daysSinceMonday = (dayOfWeek + 6) % 7; // 0 if today is Monday
const thisMonday = new Date(now.getFullYear(), now.getMonth(), now.getDate() - daysSinceMonday);

// Last full week = the Mon-Sun week that ended most recently (i.e. the week before this one)
const currentWeekStart = new Date(thisMonday);
currentWeekStart.setDate(currentWeekStart.getDate() - 7);
const currentWeekEnd = new Date(currentWeekStart);
currentWeekEnd.setDate(currentWeekEnd.getDate() + 6);

// Same week, previous quarter (13 weeks / 91 days earlier), Mon-Sun aligned
const qoqWeekStart = new Date(currentWeekStart);
qoqWeekStart.setDate(qoqWeekStart.getDate() - 91);
const qoqWeekEnd = new Date(qoqWeekStart);
qoqWeekEnd.setDate(qoqWeekEnd.getDate() + 6);

// Same week, previous year (52 weeks / 364 days earlier keeps Mon-Sun alignment)
const yoyWeekStart = new Date(currentWeekStart);
yoyWeekStart.setDate(yoyWeekStart.getDate() - 364);
const yoyWeekEnd = new Date(yoyWeekStart);
yoyWeekEnd.setDate(yoyWeekEnd.getDate() + 6);

return [{
  json: {
    client_name: items[0].json.client_name,
    domain: domain,
    ga_property_id: items[0].json.ga_property_id,
    gsc_property: gscProperty,
    accuranker_domain_id: items[0].json.accuranker_domain_id,

    week_label: fmt(currentWeekStart) + ' to ' + fmt(currentWeekEnd),

    // Current week (the week just gone, Mon-Sun)
    week_current_start: fmt(currentWeekStart),
    week_current_end: fmt(currentWeekEnd),

    // Same week, previous quarter
    week_qoq_start: fmt(qoqWeekStart),
    week_qoq_end: fmt(qoqWeekEnd),

    // Same week, previous year
    week_yoy_start: fmt(yoyWeekStart),
    week_yoy_end: fmt(yoyWeekEnd)
  }
}];

