// Normalise both sides the same way before comparing - strips protocol, www.,
// a trailing slash, and lower-cases - so a trailing slash or http(s) prefix
// coming from the Clients sheet can never cause a false "Domain not found".
function normalise(d) {
  return String(d || '')
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/\/+$/, '');
}

const domain = $('Edit Fields').item.json.domain;
const cleanDomain = normalise(domain);

for (const item of $input.all()) {
  if (item.json.domain && normalise(item.json.domain) === cleanDomain) {
    return [{ json: item.json }];
  }
}

// Not tracked in AccuRanker under this domain - fall through with no id rather
// than throwing, so the keyword-fetch nodes downstream can skip gracefully
// instead of building a "domains//keywords" URL and 404ing the whole loop.
console.warn(`AccuRanker: no domain match for "${domain}" - rankings will be skipped for this client this run.`);
return [{ json: { error: 'Domain not found', id: null, domain } }];

const merged = items[0].json;
const client = $('Calculate Weekly Periods').item.json;

// ---- GSC totals ----
const gscRows = merged.rows || [];
// Each incoming branch was tagged with gsc_period and carries the raw GSC API response fields (rows[0].clicks etc)
// Re-collect from all three GSC-tagged items via their own node outputs since Merge combines items, not fields.
const gscCurrent = $('Tag GSC Current').first().json;
const gscQoQ = $('Tag GSC QoQ').first().json;
const gscYoY = $('Tag GSC YoY').first().json;

// A failed GSC call (site not verified / no access - onError: continueRegularOutput
// upstream) comes through with no "rows" array at all, as opposed to a genuine zero-
// traffic week which still has rows: [{clicks: 0, ...}]. Track that distinction so a
// data-fetch failure is never reported as a real "-100%" drop below.
const hasRows = (item) => Array.isArray(item && item.rows);
const gsc_current_available = hasRows(gscCurrent);
const gsc_qoq_available = hasRows(gscQoQ);
const gsc_yoy_available = hasRows(gscYoY);

const gscTotal = (item) => {
  const r = (item.rows || [])[0];
  return r ? { clicks: r.clicks || 0, impressions: r.impressions || 0, ctr: r.ctr || 0, position: r.position || 0 } : { clicks: 0, impressions: 0, ctr: 0, position: 0 };
};

const gsc_current = gscTotal(gscCurrent);
const gsc_qoq = gscTotal(gscQoQ);
const gsc_yoy = gscTotal(gscYoY);

// ---- GA4 ----
const ga4Standard = $('GA4 - Weekly Metrics').first().json;
const ga4Organic = $('GA4 - Weekly Organic Metrics').first().json;

const ga4_available = Array.isArray(ga4Standard && ga4Standard.rows);
const organic_available = Array.isArray(ga4Organic && ga4Organic.rows);

const getGa4 = (resp, rangeName, metricIndex) => {
  const rows = resp.rows || [];
  const row = rows.find(r => r.dimensionValues.some(d => d.value === rangeName));
  return row ? parseFloat(row.metricValues[metricIndex].value) : 0;
};

const ga4_current = { sessions: getGa4(ga4Standard, 'week_current', 0), engagement: getGa4(ga4Standard, 'week_current', 1), newUsers: getGa4(ga4Standard, 'week_current', 2), keyEvents: getGa4(ga4Standard, 'week_current', 3) };
const ga4_qoq = { sessions: getGa4(ga4Standard, 'week_qoq', 0), engagement: getGa4(ga4Standard, 'week_qoq', 1), newUsers: getGa4(ga4Standard, 'week_qoq', 2), keyEvents: getGa4(ga4Standard, 'week_qoq', 3) };
const ga4_yoy = { sessions: getGa4(ga4Standard, 'week_yoy', 0), engagement: getGa4(ga4Standard, 'week_yoy', 1), newUsers: getGa4(ga4Standard, 'week_yoy', 2), keyEvents: getGa4(ga4Standard, 'week_yoy', 3) };

const getGa4Organic = (resp, rangeName, metricIndex) => {
  const rows = resp.rows || [];
  const row = rows.find(r => r.dimensionValues.some(d => d.value === rangeName) && r.dimensionValues.some(d => d.value === 'Organic Search'));
  return row ? parseFloat(row.metricValues[metricIndex].value) : 0;
};

const organic_current = { sessions: getGa4Organic(ga4Organic, 'week_current', 0), keyEvents: getGa4Organic(ga4Organic, 'week_current', 1) };
const organic_qoq = { sessions: getGa4Organic(ga4Organic, 'week_qoq', 0), keyEvents: getGa4Organic(ga4Organic, 'week_qoq', 1) };
const organic_yoy = { sessions: getGa4Organic(ga4Organic, 'week_yoy', 0), keyEvents: getGa4Organic(ga4Organic, 'week_yoy', 1) };

// ---- AccuRanker ----
const arCurrent = $('Tag Accuranker Current').first().json.rows || [];
const arQoQ = $('Tag Accuranker QoQ').first().json.rows || [];
const arYoY = $('Tag Accuranker YoY').first().json.rows || [];

const summariseRanks = (rows) => {
  const ranked = rows.map(k => (k.ranks && k.ranks.rank) || null).filter(r => r !== null && r > 0);
  const avg = ranked.length ? (ranked.reduce((a, b) => a + b, 0) / ranked.length) : null;
  const top3 = ranked.filter(r => r <= 3).length;
  const top10 = ranked.filter(r => r <= 10).length;
  return { avgPosition: avg, top3Count: top3, top10Count: top10, trackedKeywords: rows.length };
};

const ar_current = summariseRanks(arCurrent);
const ar_qoq = summariseRanks(arQoQ);
const ar_yoy = summariseRanks(arYoY);

// Find the biggest individual keyword rank movers (current vs previous week's own data isn't available here,
// so movers are measured current vs QoQ and current vs YoY as configured).
const byKeyword = (rows) => {
  const map = {};
  for (const k of rows) {
    if (k.keyword) map[k.keyword] = (k.ranks && k.ranks.rank) || null;
  }
  return map;
};
const curMap = byKeyword(arCurrent);
const yoyMap = byKeyword(arYoY);
const qoqMap = byKeyword(arQoQ);

const movers = [];
for (const [keyword, curRank] of Object.entries(curMap)) {
  if (curRank === null) continue;
  const qoqRank = qoqMap[keyword];
  const yoyRank = yoyMap[keyword];
  if (qoqRank && Math.abs(curRank - qoqRank) >= 5) {
    movers.push({ keyword, curRank, comparedRank: qoqRank, vs: 'same week last quarter', change: qoqRank - curRank });
  } else if (yoyRank && Math.abs(curRank - yoyRank) >= 5) {
    movers.push({ keyword, curRank, comparedRank: yoyRank, vs: 'same week last year', change: yoyRank - curRank });
  }
}
movers.sort((a, b) => Math.abs(b.change) - Math.abs(a.change));
const topMovers = movers.slice(0, 15);

// ---- Threshold-based flags ----
const pctChange = (cur, prev) => (prev === 0 || prev === null || prev === undefined) ? null : ((cur - prev) / prev) * 100;

const flags = [];
const TRAFFIC_THRESHOLD = 15; // percent
const LEADS_THRESHOLD = 20;   // percent
const RANK_THRESHOLD = 5;     // positions

function checkMetric(label, cur, prev, vsLabel, threshold, unit) {
  const pct = pctChange(cur, prev);
  if (pct !== null && Math.abs(pct) >= threshold) {
    flags.push({
      label, vsLabel, current: cur, previous: prev, pctChange: Math.round(pct * 10) / 10,
      direction: pct > 0 ? 'up' : 'down', unit
    });
  }
}

if (gsc_current_available && gsc_qoq_available) checkMetric('GSC Clicks', gsc_current.clicks, gsc_qoq.clicks, 'same week last quarter', TRAFFIC_THRESHOLD, 'clicks');
if (gsc_current_available && gsc_yoy_available) checkMetric('GSC Clicks', gsc_current.clicks, gsc_yoy.clicks, 'same week last year', TRAFFIC_THRESHOLD, 'clicks');
if (gsc_current_available && gsc_qoq_available) checkMetric('GSC Impressions', gsc_current.impressions, gsc_qoq.impressions, 'same week last quarter', TRAFFIC_THRESHOLD, 'impressions');
if (gsc_current_available && gsc_yoy_available) checkMetric('GSC Impressions', gsc_current.impressions, gsc_yoy.impressions, 'same week last year', TRAFFIC_THRESHOLD, 'impressions');
if (organic_available) checkMetric('Organic Sessions (GA4)', organic_current.sessions, organic_qoq.sessions, 'same week last quarter', TRAFFIC_THRESHOLD, 'sessions');
if (organic_available) checkMetric('Organic Sessions (GA4)', organic_current.sessions, organic_yoy.sessions, 'same week last year', TRAFFIC_THRESHOLD, 'sessions');
if (organic_available) checkMetric('Organic Leads/Key Events (GA4)', organic_current.keyEvents, organic_qoq.keyEvents, 'same week last quarter', LEADS_THRESHOLD, 'leads');
if (organic_available) checkMetric('Organic Leads/Key Events (GA4)', organic_current.keyEvents, organic_yoy.keyEvents, 'same week last year', LEADS_THRESHOLD, 'leads');
if (ga4_available) checkMetric('Total Site Leads/Key Events (GA4)', ga4_current.keyEvents, ga4_qoq.keyEvents, 'same week last quarter', LEADS_THRESHOLD, 'leads');
if (ga4_available) checkMetric('Total Site Leads/Key Events (GA4)', ga4_current.keyEvents, ga4_yoy.keyEvents, 'same week last year', LEADS_THRESHOLD, 'leads');

// Surface the gap itself rather than staying silent about it - a missing data source
// is worth knowing about even when it can't be turned into a flag.
const dataGaps = [];
if (!gsc_current_available || !gsc_qoq_available || !gsc_yoy_available) {
  dataGaps.push('Google Search Console data was not available this week (check GSC access for this site) - GSC comparisons skipped.');
}
if (!ga4_available) {
  dataGaps.push('GA4 data was not available this week (check GA4 property access) - GA4 comparisons skipped.');
}
if (!organic_available) {
  dataGaps.push('GA4 organic-traffic data was not available this week - organic comparisons skipped.');
}

if (ar_current.avgPosition !== null && ar_qoq.avgPosition !== null && Math.abs(ar_current.avgPosition - ar_qoq.avgPosition) >= RANK_THRESHOLD) {
  flags.push({ label: 'Average Keyword Position', vsLabel: 'same week last quarter', current: ar_current.avgPosition, previous: ar_qoq.avgPosition, direction: ar_current.avgPosition < ar_qoq.avgPosition ? 'improved' : 'worsened', unit: 'position' });
}
if (ar_current.avgPosition !== null && ar_yoy.avgPosition !== null && Math.abs(ar_current.avgPosition - ar_yoy.avgPosition) >= RANK_THRESHOLD) {
  flags.push({ label: 'Average Keyword Position', vsLabel: 'same week last year', current: ar_current.avgPosition, previous: ar_yoy.avgPosition, direction: ar_current.avgPosition < ar_yoy.avgPosition ? 'improved' : 'worsened', unit: 'position' });
}

// ---- Build the raw text block the AI will summarise ----
const fmtNum = (n) => (n === null || n === undefined) ? 'n/a' : (Math.round(n * 100) / 100).toLocaleString();

let raw = `Client: ${client.client_name}\nWeek covered (Mon-Sun): ${client.week_current_start} to ${client.week_current_end}\nCompared to same week last quarter: ${client.week_qoq_start} to ${client.week_qoq_end}\nCompared to same week last year: ${client.week_yoy_start} to ${client.week_yoy_end}\n\n`;

raw += `## Google Search Console (site totals)\n`;
raw += `Clicks: ${gsc_current.clicks} (last quarter same week: ${gsc_qoq.clicks}, last year same week: ${gsc_yoy.clicks})\n`;
raw += `Impressions: ${gsc_current.impressions} (last quarter same week: ${gsc_qoq.impressions}, last year same week: ${gsc_yoy.impressions})\n`;
raw += `Average CTR: ${(gsc_current.ctr * 100).toFixed(2)}% (last quarter same week: ${(gsc_qoq.ctr * 100).toFixed(2)}%, last year same week: ${(gsc_yoy.ctr * 100).toFixed(2)}%)\n`;
raw += `Average Position: ${gsc_current.position.toFixed(1)} (last quarter same week: ${gsc_qoq.position.toFixed(1)}, last year same week: ${gsc_yoy.position.toFixed(1)})\n\n`;

raw += `## GA4 — All Traffic\n`;
raw += `Sessions: ${ga4_current.sessions} (last quarter same week: ${ga4_qoq.sessions}, last year same week: ${ga4_yoy.sessions})\n`;
raw += `New Users: ${ga4_current.newUsers} (last quarter same week: ${ga4_qoq.newUsers}, last year same week: ${ga4_yoy.newUsers})\n`;
raw += `Key Events/Leads: ${ga4_current.keyEvents} (last quarter same week: ${ga4_qoq.keyEvents}, last year same week: ${ga4_yoy.keyEvents})\n\n`;

raw += `## GA4 — Organic Search Only\n`;
raw += `Organic Sessions: ${organic_current.sessions} (last quarter same week: ${organic_qoq.sessions}, last year same week: ${organic_yoy.sessions})\n`;
raw += `Organic Key Events/Leads: ${organic_current.keyEvents} (last quarter same week: ${organic_qoq.keyEvents}, last year same week: ${organic_yoy.keyEvents})\n\n`;

raw += `## AccuRanker Rankings\n`;
raw += `Average Position: ${fmtNum(ar_current.avgPosition)} (last quarter same week: ${fmtNum(ar_qoq.avgPosition)}, last year same week: ${fmtNum(ar_yoy.avgPosition)})\n`;
raw += `Keywords in Top 3: ${ar_current.top3Count} (last quarter same week: ${ar_qoq.top3Count}, last year same week: ${ar_yoy.top3Count})\n`;
raw += `Keywords in Top 10: ${ar_current.top10Count} (last quarter same week: ${ar_qoq.top10Count}, last year same week: ${ar_yoy.top10Count})\n`;
raw += `Tracked Keywords: ${ar_current.trackedKeywords}\n\n`;

if (topMovers.length) {
  raw += `## Notable Keyword Rank Movers (5+ positions)\n`;
  for (const m of topMovers) {
    const dir = m.change > 0 ? 'improved' : 'dropped';
    raw += `- "${m.keyword}": now #${m.curRank}, was #${m.comparedRank} vs ${m.vs} (${dir} ${Math.abs(m.change)} positions)\n`;
  }
  raw += `\n`;
}

raw += `## Auto-Flagged Items (threshold breaches: traffic ±${TRAFFIC_THRESHOLD}%, leads ±${LEADS_THRESHOLD}%, avg position ±${RANK_THRESHOLD})\n`;
if (flags.length === 0) {
  raw += `No metrics breached the flagging thresholds this week.\n`;
} else {
  for (const f of flags) {
    if (f.unit === 'position') {
      raw += `- ${f.label} ${f.direction} from ${fmtNum(f.previous)} to ${fmtNum(f.current)} vs ${f.vsLabel}\n`;
    } else {
      raw += `- ${f.label} ${f.direction} ${Math.abs(f.pctChange)}% (${f.previous} -> ${f.current}) vs ${f.vsLabel}\n`;
    }
  }
}

if (dataGaps.length) {
  raw += `\n## Data Gaps\n`;
  dataGaps.forEach(g => { raw += `- ${g}\n`; });
}

return [{
  json: {
    client_name: client.client_name,
    domain: client.domain,
    week_label: client.week_label,
    week_start: client.week_current_start,
    week_end: client.week_current_end,
    raw_summary: raw,
    flags,
    flagCount: flags.length,
    topMovers,

    // Extra raw numbers, kept only for the dashboard sheet log below -
    // the email path above never reads these.
    run_date: new Date().toISOString().split('T')[0],
    gsc_clicks_current: gsc_current_available ? gsc_current.clicks : null,
    gsc_clicks_yoy: gsc_yoy_available ? gsc_yoy.clicks : null,
    gsc_impressions_current: gsc_current_available ? gsc_current.impressions : null,
    gsc_avg_position_current: gsc_current_available ? gsc_current.position : null,
    ga4_sessions_current: ga4_available ? ga4_current.sessions : null,
    ga4_leads_current: ga4_available ? ga4_current.keyEvents : null,
    organic_sessions_current: organic_available ? organic_current.sessions : null,
    organic_leads_current: organic_available ? organic_current.keyEvents : null,
    accuranker_avg_position: ar_current.avgPosition,
    accuranker_top3: ar_current.top3Count,
    accuranker_top10: ar_current.top10Count,
    data_gaps: dataGaps.length ? dataGaps.join('; ') : null
  }
}];

// Turn the model's markdown reply into styled HTML for the email body.
const aiItem = $input.first().json;
// Claude's Messages API returns { content: [ { type: 'text', text: '...' } ] }.
// The message.content / response / text checks are kept as a fallback in
// case this ever points at a different (e.g. Ollama-shaped) endpoint again.
const aiContent = (Array.isArray(aiItem.content) && aiItem.content[0] && aiItem.content[0].text)
  || (aiItem.message && aiItem.message.content)
  || aiItem.response
  || aiItem.text
  || '';

// The Qwen call has onError: continueRegularOutput, so if the local AI call
// failed or timed out this item won't have message/response/text at all -
// without this fallback that used to silently send a blank email. Surface it
// instead, along with whatever raw flags were already calculated, so a
// failed AI call is obvious rather than looking like "nothing happened".
const clientName = $('Calculate Weekly Periods').first().json.client_name || 'this client';
const rawSummary = ($('Build Weekly Flags').first().json.raw_summary) || '';
const raw = aiContent || (
  `### **Weekly SEO Flags for ${clientName}**\n\n` +
  `**AI summary unavailable this week** - the AI analysis did not return a response (likely a rate limit, auth, or connection issue). ` +
  `Showing the raw flagged data below instead.\n\n${rawSummary}`
);

function escapeHtml(s) {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function inlineFormat(line) {
  line = line.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
  line = line.replace(/(^|[^*])\*([^*\n]+)\*(?!\*)/g, '$1<em>$2</em>');
  return line;
}

function mdToHtml(md) {
  const lines = escapeHtml(md).split('\n');
  let html = '';
  let inUl = false;
  let inOl = false;

  const closeLists = () => {
    if (inUl) { html += '</ul>'; inUl = false; }
    if (inOl) { html += '</ol>'; inOl = false; }
  };

  for (const rawLine of lines) {
    const line = rawLine.trim();

    if (line === '') { closeLists(); continue; }

    if (/^(\*\*\*+|---+)$/.test(line)) {
      closeLists();
      html += '<hr style="border:none;border-top:1px solid #ddd;margin:24px 0;">';
      continue;
    }

    let m;
    if ((m = line.match(/^######\s+(.*)$/))) { closeLists(); html += `<h6 style="margin:18px 0 6px;">${inlineFormat(m[1])}</h6>`; continue; }
    if ((m = line.match(/^#####\s+(.*)$/)))  { closeLists(); html += `<h5 style="margin:18px 0 6px;">${inlineFormat(m[1])}</h5>`; continue; }
    if ((m = line.match(/^####\s+(.*)$/)))   { closeLists(); html += `<h4 style="margin:18px 0 6px;">${inlineFormat(m[1])}</h4>`; continue; }
    if ((m = line.match(/^###\s+(.*)$/)))    { closeLists(); html += `<h3 style="margin:22px 0 8px;color:#1a1a1a;">${inlineFormat(m[1])}</h3>`; continue; }
    if ((m = line.match(/^##\s+(.*)$/)))     { closeLists(); html += `<h2 style="margin:24px 0 10px;color:#1a1a1a;">${inlineFormat(m[1])}</h2>`; continue; }
    if ((m = line.match(/^#\s+(.*)$/)))      { closeLists(); html += `<h1 style="margin:24px 0 10px;color:#1a1a1a;">${inlineFormat(m[1])}</h1>`; continue; }

    if ((m = line.match(/^\d+\.\s+(.*)$/))) {
      if (!inUl && !inOl) { html += '<ol style="margin:8px 0;padding-left:22px;">'; inOl = true; }
      else if (inUl) { closeLists(); html += '<ol style="margin:8px 0;padding-left:22px;">'; inOl = true; }
      html += `<li style="margin-bottom:4px;">${inlineFormat(m[1])}</li>`;
      continue;
    }

    if ((m = line.match(/^[-*]\s+(.*)$/))) {
      if (!inOl && !inUl) { html += '<ul style="margin:8px 0;padding-left:22px;">'; inUl = true; }
      else if (inOl) { closeLists(); html += '<ul style="margin:8px 0;padding-left:22px;">'; inUl = true; }
      html += `<li style="margin-bottom:4px;">${inlineFormat(m[1])}</li>`;
      continue;
    }

    closeLists();
    html += `<p style="margin:10px 0;">${inlineFormat(line)}</p>`;
  }

  closeLists();
  return html;
}

const bodyHtml = mdToHtml(raw);

const html = `<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.6;color:#222222;max-width:680px;">${bodyHtml}</div>`;

return [{ json: { html, flagCount: $('Build Weekly Flags').first().json.flagCount } }];
